head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[input > M > setIoFormat]<br/>dataType=date 일때 InputBox 컴포넌트의 ioFormat 속성과 displayFormat 속성을 설정합니다.",
    "validation" : [
        "dataType 속성값이 date 일때 적용됩니다.",
        "ioFormat(필수) 파라미터로 마스크 문자를 사용하여 입력되는 날짜의 포맷을 설정합니다.",
        "ioFormat(필수) 파라미터로 ''(Empty String) 설정 시 기본값인 'yyyyMMdd' 가 적용됩니다.",
        "displayFormat(선택) 파라미터로 마스크 문자를 사용하여 표시되는 날짜의 포맷을 설정합니다.",
        "displayFormat(선택) 파라미터로 값을 생략 시 기존 displayFormat 속성값을 유지합니다.",
        "displayFormat(선택) 파라미터로 ''(Empty String) 설정 시 기존 displayFormat 속성값을 유지합니다.",
        "컴포넌트에 입력값이 있는 상태에서 포맷을 변경하면, 변경된 ioFormat 속성의 포맷에 맞게 입력값이 변경되고 onchange 이벤트도 발생합니다.", 
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.get_text = function(target) {    
    let rtn = '';
    let tagName = target.render.tagName

    if (tagName !== "INPUT") {
        rtn = target.render.textContent
        wf_body_bottom.getObj("scwin").setReturnValue("text : " + rtn);    
    }
    else {
        rtn = target.render.value
        wf_body_bottom.getObj("scwin").setReturnValue("text : " + rtn);   
    }    
}



scwin.get_text_edit = function(target) {    
    let rtn = '';
    let tagName = target.tagName

    if (tagName !== "INPUT") {
        rtn = target.textContent
        wf_body_bottom.getObj("scwin").setReturnValue("text : " + rtn);    
    }
    else {
        rtn = target.value
        wf_body_bottom.getObj("scwin").setReturnValue("text : " + rtn);   
    }    
}



// target1
scwin.btn_setIoFormat1_onclick = function (e) {
    target1.setIoFormat("MMddyyyy", "yyyy/MM/dd");
    target1.setValue("01312008");
    target1.focus();
};

scwin.btn_getText1_onclick = function (e) {
    scwin.get_text(target1);
}

// target2
scwin.btn_setIoFormat2_onclick = function (e) {
    target2.setIoFormat("", "yyyy/MM/dd");
    target2.setValue("20080131");
    target2.focus();
};

scwin.btn_getText2_onclick = function (e) {
    scwin.get_text(target2);
}

// target3
scwin.btn_setIoFormat3_onclick = function (e) {
    target3.setIoFormat("MMddyyyy");
    target3.setValue("01312008");
    target3.focus();
};

scwin.btn_getText3_onclick = function (e) {
    scwin.get_text(target3);
};

// target4
scwin.btn_setIoFormat4_onclick = function (e) {
    target4.setIoFormat("MMddyyyy");
    target4.setValue("01312008");
    target4.focus();
};

scwin.btn_getText4_onclick = function (e) {
    scwin.get_text(target4);
};

// target5
scwin.btn_setIoFormat5_onclick = function (e) {
    target5.setIoFormat("yyyyMMdd", "yyyy/MM/dd");
    target5.setValue("20250923");
    target5.focus();
};

scwin.btn_getText5_onclick = function (e) {
    scwin.get_text(target5);
};


scwin.btn_setAll_onclick = function (e) {
    for (var i = 1; i < 6; i ++)
        eval("scwin.btn_setIoFormat"+i+"_onclick()");
}

scwin.btn_getAll_onclick = function (e) {
    for (var i = 1; i < 6; i ++)
        eval("scwin.btn_getText"+i+"_onclick()");
};


scwin.target_onfocus = function (e) {
    scwin.get_text_edit(e.target);
};

scwin.target5_onchange = function (info) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target5_onchange=====");      
};
